#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int to, rev;
    long long capacity, cost;
};

struct MinCostFlow {
    int n;
    std::vector<std::vector<Edge>> graph;
    std::vector<long long> dist;
    std::vector<int> prevnode, prevedge;
    std::vector<long long> potential;

    MinCostFlow(int n) : n(n), graph(n), dist(n), prevnode(n), prevedge(n), potential(n, 0) {}

    void addEdge(int u, int v, long long cap, long long cost) {
        graph[u].push_back({v, (int)graph[v].size(), cap, cost});
        graph[v].push_back({u, (int)graph[u].size() - 1, 0, -cost});
    }

    std::pair<long long, long long> minCostMaxFlow(int s, int t) {
        long long flow = 0, flowCost = 0;
        while (true) {
            std::fill(dist.begin(), dist.end(), LLONG_MAX);
            dist[s] = 0;
            std::priority_queue<std::pair<long long, int>,
                                std::vector<std::pair<long long, int>>,
                                std::greater<>> pq;
            pq.push({0, s});
            while (!pq.empty()) {
                auto [d, u] = pq.top(); pq.pop();
                if (d > dist[u]) continue;
                for (int i = 0; i < (int)graph[u].size(); ++i) {
                    auto &e = graph[u][i];
                    if (e.capacity > 0) {
                        long long nd = d + e.cost + potential[u] - potential[e.to];
                        if (nd < dist[e.to]) {
                            dist[e.to] = nd;
                            prevnode[e.to] = u;
                            prevedge[e.to] = i;
                            pq.push({nd, e.to});
                        }
                    }
                }
            }
            if (dist[t] == LLONG_MAX) break;
            for (int i = 0; i < n; ++i) {
                if (dist[i] < LLONG_MAX) potential[i] += dist[i];
            }
            long long df = LLONG_MAX;
            for (int u = t; u != s; u = prevnode[u]) {
                auto &e = graph[prevnode[u]][prevedge[u]];
                df = std::min(df, e.capacity);
            }
            flow += df;
            for (int u = t; u != s; u = prevnode[u]) {
                auto &e = graph[prevnode[u]][prevedge[u]];
                e.capacity -= df;
                graph[u][e.rev].capacity += df;
                flowCost += df * e.cost;
            }
        }
        return {flow, flowCost};
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    string s;
    cin >> n >> s;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    vector<int> cnt(26, 0);
    for (char c : s) cnt[c - 'a']++;

    int source = n + 98;
    int target = source + 1;
    MinCostFlow g(n + 100);

    for (int i = 0; i * 2 < n; ++i) {
        g.addEdge(i, target, 2, 0);
    }

    for (int i = 0; i < 26; ++i) {
        g.addEdge(source, n + i, 0, cnt[i]);
        for (int j = 0; j * 2 < n; ++j) {
            if (s[j] == s[n - j - 1]) {
                int w = 0;
                if (s[j] - 'a' == i) w = -std::max(a[j], a[n - j - 1]);
                g.addEdge(n + i, j, w, 1);
            } else {
                int w = 0;
                if (s[j] - 'a' == i) w -= a[j];
                if (s[n - j - 1] - 'a' == i) w -= a[n - j - 1];
                g.addEdge(n + i, j, w, 1);
            }
        }
    }

    auto [flow, cost] = g.minCostMaxFlow(source, target);
    cout << -cost << "\n";

    return 0;
}

